export const GONGLU_DATA = '';
const BYTES = Uint8Array.from(atob(GONGLU_DATA), c => c.charCodeAt(0));
export function blockGONGLU(x, y, z) {
  const [sx, sy, sz] = GONGLU_SIZE;
  if (x < 0 || y < 0 || z < 0 || x >= sx || y >= sy || z >= sz) return null;
  const index = (y * sz + z) * sx + x;
  let value = 0;
  for (let k = 0; k < GONGLU_BITS; k++) {
    const bit = index * GONGLU_BITS + k;
    value |= ((BYTES[bit >> 3] >> (bit & 7)) & 1) << k;
  }
  return GONGLU_PALETTE[value];
}
export function buildLitematicGONGLU(grid, origin, mapBlock, groupFor, emitShape) {
  let bit = 0;
  const read = () => {
    let value = 0;
    for (let k = 0; k < GONGLU_BITS; k++, bit++) value |= ((BYTES[bit >> 3] >> (bit & 7)) & 1) << k;
    return value;
  };
  const [SX, SY, SZ] = GONGLU_SCALE;
  for (let my = 0; my < GONGLU_SIZE[1]; my++) {
    for (let mz = 0; mz < GONGLU_SIZE[2]; mz++) {
      for (let mx = 0; mx < GONGLU_SIZE[0]; mx++) {
        const entry = GONGLU_PALETTE[read()];
        if (!entry || entry[0] === 'minecraft:air') continue;
        const wx = origin.x + mx * SX, wy = origin.y + my * SY, wz = origin.z + mz * SZ;
        const mapped = mapBlock(entry[0], entry[1] ?? {}, mx, my, mz);
        if (mapped) for (let dz = 0; dz < SZ; dz++) for (let dy = 0; dy < SY; dy++) for (let dx = 0; dx < SX; dx++) {
          grid.set(wx + dx, wy + dy, wz + dz, mapped);
        }
        const group = groupFor(wx, wy, wz);
        if (group) emitShape(entry[0], entry[1] ?? {}, wx, wy, wz, group, SX, SY, SZ);
      }
    }
  }
}
